-- Security assertions (REG-AUTH/SEC), originally red until P02-03/04, now green; includes the P06-01 tenant administration matrix.
-- Synthetic SQL actor simulation; every write is rolled back.
begin;
select plan(425);
insert into public.agencies(id,name,code) values
 ('12000000-0000-0000-0000-000000000001','Security A','P2-SEC-A'),
 ('12000000-0000-0000-0000-000000000002','Security B','P2-SEC-B');
insert into public.portal_profiles(id,auth_user_id,full_name,email) values
 ('22000000-0000-0000-0000-000000000001','32000000-0000-0000-0000-000000000001','Security agent','security@example.test');
insert into public.agency_memberships(user_id,agency_id,role) values
 ('22000000-0000-0000-0000-000000000001','12000000-0000-0000-0000-000000000001','agent');
insert into public.enrollment_applications(id,agency_id,assigned_agent_id,status,data) values
 ('42000000-0000-0000-0000-000000000001','12000000-0000-0000-0000-000000000001','22000000-0000-0000-0000-000000000001','submitted','{"values":{"first_name":"Confirmed"}}'),
 ('42000000-0000-0000-0000-000000000002','12000000-0000-0000-0000-000000000002',null,'draft','{}');
insert into public.enrollment_application_messages(application_id,body,visibility) values
 ('42000000-0000-0000-0000-000000000001','Private staff note','internal'),
 ('42000000-0000-0000-0000-000000000001','Agency message','agency');
insert into public.enrollment_application_documents(id,application_id,category,storage_path,filename) values
 ('52000000-0000-0000-0000-000000000001','42000000-0000-0000-0000-000000000001','Passport','42000000-0000-0000-0000-000000000001/own.pdf','own.pdf'),
 ('52000000-0000-0000-0000-000000000002','42000000-0000-0000-0000-000000000002','Passport','42000000-0000-0000-0000-000000000002/foreign.pdf','foreign.pdf');
set local role authenticated;
set local request.jwt.claim.sub='32000000-0000-0000-0000-000000000001';
select is((select count(*)::int from public.enrollment_application_messages where visibility='agency'),1,'agent retains public agency messages');
select is((select count(*)::int from public.enrollment_applications where id='42000000-0000-0000-0000-000000000002'),0,'agent cannot read foreign agency application');
select is((select count(*)::int from public.enrollment_application_messages where visibility='internal'),0,'SEC-01 internal notes are hidden');
with changed as (update public.enrollment_application_documents set storage_path='42000000-0000-0000-0000-000000000002/foreign.pdf' where id='52000000-0000-0000-0000-000000000001' returning id)
select is((select count(*)::int from changed),0,'SEC-02 document locator cannot be substituted');
select throws_ok($$insert into public.enrollment_application_courses(application_id,course_id) values ('42000000-0000-0000-0000-000000000001','forged')$$,'42501',null,'SEC-04 submitted course changes denied');
select throws_ok($$insert into public.enrollment_application_versions(application_id,version,snapshot) values ('42000000-0000-0000-0000-000000000001',999,'{}')$$,'42501',null,'SEC-12 snapshot forgery denied');
select throws_ok($$insert into public.enrollment_application_status_history(application_id,new_status,actor_name) values ('42000000-0000-0000-0000-000000000001','enrolled','Forged admin')$$,'42501',null,'SEC-12 history forgery denied');
select throws_ok($$select public.portal_save_document_review('42000000-0000-0000-0000-000000000001','{"first_name":"Changed"}','{}','[]','[]')$$,'42501',null,'SEC-03 submitted review changes denied');
-- Separate parent-link case on editable draft, so status cannot mask the issue.
reset role;
update public.enrollment_applications set status='draft' where id='42000000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$select public.portal_save_document_review('42000000-0000-0000-0000-000000000001','{}','{}','[]','[{"field":"first_name","documentId":"52000000-0000-0000-0000-000000000002","state":"confirmed"}]')$$,'42501',null,'SEC-03 foreign-document review linkage denied');
reset role;
update public.agencies set status='Inactive' where id='12000000-0000-0000-0000-000000000001';
set local role authenticated;
select is((select count(*)::int from public.enrollment_applications where id='42000000-0000-0000-0000-000000000001'),0,'SEC-05 inactive agency loses application access');
reset role;
update public.portal_profiles set status='Inactive' where id='22000000-0000-0000-0000-000000000001';
set local role authenticated;
with changed as (update public.portal_profiles set status='Active' where id='22000000-0000-0000-0000-000000000001' returning id)
select is((select count(*)::int from changed),0,'SEC-05 self-reactivation denied');
-- P06-01 REG-AUTH/SEC tenant administration matrix: scoped commands, no platform escalation, domain verify/revoke.
reset role;
insert into auth.users(id,email,email_confirmed_at) values
 ('a0000000-0000-0000-0000-000000000001','admin-a@example.test',now()),('a0000000-0000-0000-0000-000000000002','admin-b@example.test',now()),
 ('a0000000-0000-0000-0000-000000000003','platform@example.test',now()),('a0000000-0000-0000-0000-000000000004','editor-a@example.test',now()),
 ('a0000000-0000-0000-0000-000000000005','newcomer@example.test',now());
insert into public.agencies(id,name,code) values ('12000000-0000-0000-0000-0000000000a1','P06 shared agency','P6-SHARED');
insert into public.tenants(id,slug,name) values ('1a000000-0000-0000-0000-000000000001','p06-a','Institution A'),('1a000000-0000-0000-0000-000000000002','p06-b','Institution B');
insert into public.tenant_memberships(tenant_id,auth_user_id,role) values
 ('1a000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000001','tenant_admin'),
 ('1a000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000004','editor'),
 ('1a000000-0000-0000-0000-000000000002','a0000000-0000-0000-0000-000000000002','tenant_admin');
insert into public.platform_admins(auth_user_id) values ('a0000000-0000-0000-0000-000000000003');
insert into public.tenant_domains(hostname,tenant_id,verified_at,verification_evidence) values
 ('a.p06.example.test','1a000000-0000-0000-0000-000000000001',now(),'DNS proof'),('b.p06.example.test','1a000000-0000-0000-0000-000000000002',now(),'DNS proof');
set local role authenticated;
set local request.jwt.claim.sub='a0000000-0000-0000-0000-000000000001';
select is(public.tenant_admin_overview('1a000000-0000-0000-0000-000000000001')->'tenant'->>'name','Institution A','tenant admin reads own institution overview');
select throws_ok($$select public.tenant_admin_overview('1a000000-0000-0000-0000-000000000002')$$,'42501',null,'tenant admin cannot read another institution');
select lives_ok($$select public.tenant_update_details('1a000000-0000-0000-0000-000000000001','  Institution A Renamed ')$$,'tenant admin updates own details');
select is((select name from public.tenants where id='1a000000-0000-0000-0000-000000000001'),'Institution A Renamed','details are trimmed and saved');
select is((select count(*)::int from public.tenant_access_audit where tenant_id='1a000000-0000-0000-0000-000000000001' and action='details' and actor='a0000000-0000-0000-0000-000000000001'),1,'details change is audited with the actor');
select throws_ok($$select public.tenant_update_details('1a000000-0000-0000-0000-000000000002','Hijack')$$,'42501',null,'tenant admin cannot rename another institution');
select throws_ok($$select public.tenant_update_details('1a000000-0000-0000-0000-000000000001','   ')$$,'22023',null,'blank institution name rejected');
select lives_ok($$select public.tenant_grant_membership('1a000000-0000-0000-0000-000000000001','  Newcomer@Example.test ','staff',true)$$,'tenant admin adds a member by email');
select is((select count(*)::int from public.tenant_member_invites where tenant_id='1a000000-0000-0000-0000-000000000001' and email='newcomer@example.test' and role='staff' and accepted_at is null),1,'adding a member by email records an invitation, not a membership');
select lives_ok($$select public.tenant_grant_membership('1a000000-0000-0000-0000-000000000001','nobody@example.test','staff',true)$$,'an address without an account gets exactly the same response');
set local request.jwt.claim.sub='a0000000-0000-0000-0000-000000000005';
set local request.headers='{"x-tenant-domain":"a.p06.example.test"}';
select is(public.tenant_accept_pending_invites(),1,'the invited account receives its role when it signs in');
select is((select role from public.tenant_memberships where tenant_id='1a000000-0000-0000-0000-000000000001' and auth_user_id='a0000000-0000-0000-0000-000000000005'),'staff','the accepted invitation created the membership with the invited role');
set local request.headers='{}';
set local request.jwt.claim.sub='a0000000-0000-0000-0000-000000000001';
select throws_ok($$select public.tenant_grant_membership('1a000000-0000-0000-0000-000000000001','newcomer@example.test','platform_admin',true)$$,'22023',null,'platform role cannot be granted through membership');
select throws_ok($$select public.tenant_grant_membership('1a000000-0000-0000-0000-000000000002','newcomer@example.test','staff',true)$$,'42501',null,'tenant admin cannot add members to another institution');
select throws_ok($$insert into public.platform_admins(auth_user_id) values ('a0000000-0000-0000-0000-000000000005')$$,'42501',null,'tenant admin cannot write platform admins directly');
select throws_ok($$insert into public.tenant_memberships(tenant_id,auth_user_id,role) values ('1a000000-0000-0000-0000-000000000002','a0000000-0000-0000-0000-000000000005','tenant_admin')$$,'42501',null,'memberships are not directly writable');
select throws_ok($$select public.tenant_set_membership('1a000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000001','viewer',true)$$,'23514',null,'the last tenant administrator cannot be demoted');
select throws_ok($$select public.tenant_set_agency('1a000000-0000-0000-0000-000000000001','12000000-0000-0000-0000-0000000000a1',true)$$,'42501',null,'agency links are platform-only');
select lives_ok($$select public.tenant_claim_domain('1a000000-0000-0000-0000-000000000001','New.P06.Example.test')$$,'tenant admin claims a hostname');
select is(public.tenant_resolve('new.p06.example.test'),null,'a claimed hostname resolves nothing until verified');
select throws_ok($$select public.tenant_claim_domain('1a000000-0000-0000-0000-000000000001','b.p06.example.test')$$,'23505',null,'a hostname owned by another institution cannot be claimed');
select throws_ok($$select public.tenant_verify_domain('1a000000-0000-0000-0000-000000000001','new.p06.example.test','self-attested')$$,'42501',null,'tenant admin cannot verify a domain');
select throws_ok($$select public.tenant_revoke_domain('1a000000-0000-0000-0000-000000000002','b.p06.example.test','hostile')$$,'42501',null,'tenant admin cannot revoke another institution domain');
select throws_ok($$select public.tenant_revoke_domain('1a000000-0000-0000-0000-000000000001','a.p06.example.test','lockout')$$,'23514',null,'the only verified domain cannot be revoked by a tenant admin');
set local request.jwt.claim.sub='a0000000-0000-0000-0000-000000000004';
select throws_ok($$select public.tenant_update_details('1a000000-0000-0000-0000-000000000001','Editor rename')$$,'42501',null,'editor cannot administer the institution');
select throws_ok($$select public.tenant_grant_membership('1a000000-0000-0000-0000-000000000001','newcomer@example.test','tenant_admin',true)$$,'42501',null,'editor cannot self-escalate by granting roles');
set local request.jwt.claim.sub='a0000000-0000-0000-0000-000000000003';
select throws_ok($$select public.tenant_verify_domain('1a000000-0000-0000-0000-000000000001','new.p06.example.test','  ')$$,'22023',null,'verification needs evidence');
select lives_ok($$select public.tenant_verify_domain('1a000000-0000-0000-0000-000000000001','new.p06.example.test','DNS TXT record checked')$$,'platform admin verifies a claimed domain');
select is(public.tenant_resolve('new.p06.example.test'),'1a000000-0000-0000-0000-000000000001'::uuid,'verified domain resolves to its institution');
select throws_ok($$select public.tenant_verify_domain('1a000000-0000-0000-0000-000000000002','new.p06.example.test','wrong tenant')$$,'23505',null,'a domain cannot be verified for another institution');
select lives_ok($$select public.tenant_set_agency('1a000000-0000-0000-0000-000000000001','12000000-0000-0000-0000-0000000000a1',true)$$,'platform admin links a shared agency');
select lives_ok($$select public.tenant_set_agency('1a000000-0000-0000-0000-000000000002','12000000-0000-0000-0000-0000000000a1',true)$$,'the same agency is shared with a second institution');
select lives_ok($$select public.tenant_set_agency('1a000000-0000-0000-0000-000000000001','12000000-0000-0000-0000-0000000000a1',false)$$,'platform admin ends one link');
select is((select count(*)::int from public.agency_tenants where agency_id='12000000-0000-0000-0000-0000000000a1' and tenant_id='1a000000-0000-0000-0000-000000000002' and active),1,'the other institution keeps the shared agency');
reset role;
select is((select status from public.agencies where id='12000000-0000-0000-0000-0000000000a1'),'Active','the shared agency itself is untouched');
set local role authenticated;
set local request.jwt.claim.sub='a0000000-0000-0000-0000-000000000003';
set local request.jwt.claim.sub='a0000000-0000-0000-0000-000000000001';
select lives_ok($$select public.tenant_revoke_domain('1a000000-0000-0000-0000-000000000001','a.p06.example.test','Retired hostname')$$,'tenant admin revokes a domain once another verified one exists');
select is(public.tenant_resolve('a.p06.example.test'),null,'a revoked domain stops resolving immediately');
select is((select details->>'reason' from public.tenant_access_audit where tenant_id='1a000000-0000-0000-0000-000000000001' and action='domain_revoke'),'Retired hostname','revocation is audited with its reason');
-- P06-02 versioned configuration: schema validation, versioning, restore, secret safety, workflow pinning.
set local request.jwt.claim.sub='a0000000-0000-0000-0000-000000000001';
select lives_ok($$select public.tenant_config_save_draft('1a000000-0000-0000-0000-000000000001','branding','{"primaryColor":"#112233","headingFont":"Georgia"}',0)$$,'valid branding draft is saved');
select throws_ok($$select public.tenant_config_save_draft('1a000000-0000-0000-0000-000000000001','branding','{"primaryColor":"blue"}',0)$$,'22023',null,'invalid colour rejected');
select throws_ok($$select public.tenant_config_save_draft('1a000000-0000-0000-0000-000000000001','branding','{"primaryColor":"#112233","logo":"x"}',0)$$,'22023',null,'unknown branding field rejected');
select throws_ok($$select public.tenant_config_save_draft('1a000000-0000-0000-0000-000000000001','workflow','{"statuses":["draft","submitted","enrolled"],"transitions":[{"from":"draft","to":"submitted"}]}',0)$$,'22023',null,'workflow with an unreachable status rejected');
select throws_ok($$select public.tenant_config_save_draft('1a000000-0000-0000-0000-000000000001','workflow','{"statuses":["draft","submitted","enrolled"],"transitions":[{"from":"draft","to":"submitted"},{"from":"submitted","to":"enrolled"},{"from":"enrolled","to":"submitted"}]}',0)$$,'22023',null,'transition out of a terminal status rejected');
select throws_ok($$select public.tenant_config_save_draft('1a000000-0000-0000-0000-000000000001','roles','{"roles":{"tenant_admin":["cms.read"]}}',0)$$,'22023',null,'administrators cannot be stripped of member and configuration management');
select throws_ok($$select public.tenant_config_save_draft('1a000000-0000-0000-0000-000000000001','roles','{"roles":{"platform_admin":["cms.read"],"tenant_admin":["members.manage","config.manage"]}}',0)$$,'22023',null,'a platform role cannot be defined');
select throws_ok($$select public.tenant_config_save_draft('1a000000-0000-0000-0000-000000000001','integration','{"integrations":[{"provider":"azure","enabled":true,"settings":{"endpoint":"eyJhbGciOiJIUzI1NiJ9.payload.signature"}}]}',0)$$,'22023',null,'a credential-looking setting value is rejected');
select throws_ok($$select public.tenant_config_save_draft('1a000000-0000-0000-0000-000000000001','integration','{"integrations":[{"provider":"azure","enabled":true,"settings":{"apiKey":"x"}}]}',0)$$,'22023',null,'a credential-named setting is rejected');
select throws_ok($$select public.tenant_config_save_draft('1a000000-0000-0000-0000-000000000001','integration','{"integrations":[{"provider":"azure","enabled":true,"secretNames":["sk_live_abcdef123456"]}]}',0)$$,'22023',null,'a secret value cannot be stored as a secret name');
select lives_ok($$select public.tenant_config_save_draft('1a000000-0000-0000-0000-000000000001','integration','{"integrations":[{"provider":"azure","enabled":true,"secretNames":["EF_AZURE_DOCUMENT_API_KEY"],"settings":{"model":"prebuilt-idDocument"}}]}',0)$$,'integration stores environment variable names only');
select throws_ok($$select public.tenant_config_save_draft('1a000000-0000-0000-0000-000000000001','branding','{"primaryColor":"#112233"}',7)$$,'40001',null,'a stale base version is rejected');
select throws_ok($$select public.tenant_config_save_draft('1a000000-0000-0000-0000-000000000002','branding','{"primaryColor":"#112233"}',0)$$,'42501',null,'tenant admin cannot configure another institution');
select throws_ok($$insert into public.tenant_config_versions(tenant_id,kind,state,config) values ('1a000000-0000-0000-0000-000000000001','branding','draft','{}')$$,'42501',null,'configuration is not directly writable');
select is(public.tenant_config_publish('1a000000-0000-0000-0000-000000000001','branding',0),1,'first publish is version 1');
select lives_ok($$select public.tenant_config_save_draft('1a000000-0000-0000-0000-000000000001','branding','{"primaryColor":"#445566","bodyFont":"Verdana"}',1)$$,'next draft is based on version 1');
select throws_ok($$select public.tenant_config_publish('1a000000-0000-0000-0000-000000000001','branding',0)$$,'40001',null,'publishing from a stale base is rejected');
select is(public.tenant_config_publish('1a000000-0000-0000-0000-000000000001','branding',1),2,'second publish is version 2');
select is((select count(*)::int from public.tenant_config_versions where tenant_id='1a000000-0000-0000-0000-000000000001' and kind='branding' and state='published'),1,'exactly one published version per kind');
select is(public.tenant_config_effective('1a000000-0000-0000-0000-000000000001','branding')->>'version','2','effective branding is the latest published version');
select lives_ok($$select public.tenant_config_restore('1a000000-0000-0000-0000-000000000001','branding',1)$$,'an old version can be restored as a draft');
select is((select restored_from from public.tenant_config_versions where tenant_id='1a000000-0000-0000-0000-000000000001' and kind='branding' and state='draft'),1,'the restored draft records its source version');
select is(public.tenant_config_effective('1a000000-0000-0000-0000-000000000001','branding')->>'version','2','restoring changes nothing until published');
select is(public.tenant_config_publish('1a000000-0000-0000-0000-000000000001','branding',2),3,'restore is published as a new version, history intact');
select is(public.tenant_config_effective('1a000000-0000-0000-0000-000000000001','branding')->'config'->>'primaryColor','#112233','restored configuration equals version 1');
select is((select count(*)::int from public.tenant_config_versions where tenant_id='1a000000-0000-0000-0000-000000000001' and kind='branding' and state<>'draft'),3,'all three versions are retained');
select is(public.tenant_config_effective('1a000000-0000-0000-0000-000000000001','workflow')->>'source','default','no published workflow falls back to safe defaults');
select is((select count(*)::int from public.tenant_access_audit where tenant_id='1a000000-0000-0000-0000-000000000001' and action='config_publish' and actor='a0000000-0000-0000-0000-000000000001'),3,'each publish is audited with its actor');
set local request.jwt.claim.sub='a0000000-0000-0000-0000-000000000004';
select throws_ok($$select public.tenant_config_save_draft('1a000000-0000-0000-0000-000000000001','branding','{"primaryColor":"#000000"}',3)$$,'42501',null,'an editor cannot change configuration');
select throws_ok($$select public.tenant_config_effective('1a000000-0000-0000-0000-000000000001','integration')$$,'42501',null,'integration configuration is administrator-only');
select lives_ok($$select public.tenant_config_effective('1a000000-0000-0000-0000-000000000001','branding')$$,'members can read the effective branding');
reset role;
select throws_ok($$update public.tenant_config_versions set config='{"primaryColor":"#ffffff"}' where tenant_id='1a000000-0000-0000-0000-000000000001' and kind='branding' and version=1$$,'55000',null,'a superseded version is immutable');
select throws_ok($$delete from public.tenant_config_versions where tenant_id='1a000000-0000-0000-0000-000000000001'$$,'55000',null,'configuration history cannot be deleted');
select is((select count(*)::int from public.tenant_config_versions where config::text ~ '(eyJ|sk_live)'),0,'no credential value exists in stored configuration');
-- Workflow pinning: platform admin publishes versions for institution B; applications keep the version in force at creation.
set local role authenticated;
set local request.jwt.claim.sub='a0000000-0000-0000-0000-000000000003';
select lives_ok($$select public.tenant_config_save_draft('1a000000-0000-0000-0000-000000000002','workflow','{"statuses":["draft","submitted","under_review","enrolled"],"transitions":[{"from":"draft","to":"submitted"},{"from":"submitted","to":"under_review"},{"from":"under_review","to":"enrolled"}]}',0)$$,'platform admin drafts a workflow for an institution');
select is(public.tenant_config_publish('1a000000-0000-0000-0000-000000000002','workflow',0),1,'workflow version 1 published');
reset role;
insert into public.enrollment_applications(id,agency_id,tenant_id,status,data) values ('42000000-0000-0000-0000-0000000000b1','12000000-0000-0000-0000-0000000000a1','1a000000-0000-0000-0000-000000000002','draft','{}');
set local role authenticated;
select lives_ok($$select public.tenant_config_save_draft('1a000000-0000-0000-0000-000000000002','workflow','{"statuses":["draft","submitted","under_review","action_required","enrolled"],"transitions":[{"from":"draft","to":"submitted"},{"from":"submitted","to":"under_review"},{"from":"under_review","to":"action_required"},{"from":"action_required","to":"under_review"},{"from":"under_review","to":"enrolled"}]}',1)$$,'a second workflow version is drafted');
select is(public.tenant_config_publish('1a000000-0000-0000-0000-000000000002','workflow',1),2,'workflow version 2 published');
reset role;
insert into public.enrollment_applications(id,agency_id,tenant_id,status,data) values ('42000000-0000-0000-0000-0000000000b2','12000000-0000-0000-0000-0000000000a1','1a000000-0000-0000-0000-000000000002','draft','{}');
select is((select v.version from public.enrollment_applications a join public.tenant_config_versions v on v.id=a.workflow_version_id where a.id='42000000-0000-0000-0000-0000000000b1'),1,'an existing application stays pinned to the version it started on');
select is((select v.version from public.enrollment_applications a join public.tenant_config_versions v on v.id=a.workflow_version_id where a.id='42000000-0000-0000-0000-0000000000b2'),2,'a new application pins the newly published version');
update public.enrollment_applications set workflow_version_id=null where id='42000000-0000-0000-0000-0000000000b1';
select is((select v.version from public.enrollment_applications a join public.tenant_config_versions v on v.id=a.workflow_version_id where a.id='42000000-0000-0000-0000-0000000000b1'),1,'the pinned version cannot be changed afterwards');
-- P06-04 enforcement: default config equals the hard-coded rules; published roles/pinned workflows are enforced server-side.
reset role;
insert into auth.users(id,email) values ('a0000000-0000-0000-0000-000000000006','viewer-a@example.test');
insert into public.tenant_memberships(tenant_id,auth_user_id,role) values ('1a000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000006','viewer');
insert into public.cms_pages(id,slug,title,tenant_id) values ('p06-page','p06-page','Original','1a000000-0000-0000-0000-000000000001');
-- P08-04 (deliberate): the default workflow no longer contains under_review / offer_issued, so parity is over the 8 default statuses (64 pairs).
select is((select count(*)::int from (select f,t from unnest(array['draft','submitted','action_required','offer_accepted','coe_issued','enrolled','rejected','withdrawn']) f cross join unnest(array['draft','submitted','action_required','offer_accepted','coe_issued','enrolled','rejected','withdrawn']) t
  where public.portal_legacy_transition_allowed(f,t) is distinct from public.portal_pinned_transition_allowed(public.tenant_config_defaults('workflow'),f,t,null,true)) x),0,'the default workflow allows exactly the hard-coded transitions (64 pairs)');
select is(public.portal_pinned_transition_allowed('{"transitions":[{"from":"draft","to":"submitted"}]}','draft','submitted','tenant_admin',true),false,'a configured workflow cannot move a draft through the reviewer command');
select is(public.portal_pinned_transition_allowed('{"transitions":[{"from":"submitted","to":"rejected","roles":["tenant_admin"]}]}','submitted','rejected','staff',false),false,'a role-limited transition denies other roles');
select is(public.portal_pinned_transition_allowed('{"transitions":[{"from":"submitted","to":"rejected","roles":["tenant_admin"]}]}','submitted','rejected','tenant_admin',false),true,'a role-limited transition admits the named role');
select is(public.portal_pinned_transition_allowed('{"transitions":[{"from":"submitted","to":"rejected","roles":["tenant_admin"]}]}','submitted','rejected',null,true),true,'platform administrators are not role-limited');
select is(public.portal_pinned_transition_allowed('{"transitions":[{"from":"submitted","to":"rejected","roles":["tenant_admin"]}]}','submitted','rejected',null,false),false,'a caller without an institution role cannot use a role-limited transition');
set local role authenticated;
set local request.jwt.claim.sub='a0000000-0000-0000-0000-000000000001';
