create temporary table p07_probe(msg text);
create temporary table p07_base as select (select count(*)::int from public.admission_event_outbox where application_id='42000000-0000-0000-0000-0000000000b2' and event='application_status_changed') events;
set local request.jwt.claim.sub='a0000000-0000-0000-0000-000000000003';
set local request.headers='{"x-tenant-domain":"b.p06.example.test"}';
do $$ declare e int; d int; begin
  perform public.portal_set_application_status('42000000-0000-0000-0000-0000000000b2','action_required','needs fix');
  select count(*) into e from public.admission_event_outbox where application_id='42000000-0000-0000-0000-0000000000b2' and event='application_status_changed';
  select count(*) into d from public.notification_deliveries where application_id='42000000-0000-0000-0000-0000000000b2';
  raise exception 'probe:%:%', e, d;
exception when others then insert into p07_probe values (sqlerrm);
end $$;
select is((select msg from p07_probe),'probe:'||((select events from p07_base)+1)||':1','inside the transaction the transition wrote one event and one delivery');
select is((select count(*)::int from public.admission_event_outbox where application_id='42000000-0000-0000-0000-0000000000b2' and event='application_status_changed'),(select events from p07_base),'a rolled-back transition leaves no event');
select is((select count(*)::int from public.notification_deliveries where application_id='42000000-0000-0000-0000-0000000000b2'),0,'a rolled-back transition leaves no delivery');
select is((select status from public.enrollment_applications where id='42000000-0000-0000-0000-0000000000b2'),'under_review','a rolled-back transition leaves the status unchanged');
set local role authenticated;
select lives_ok($$select public.portal_set_application_status('42000000-0000-0000-0000-0000000000b2','action_required','needs fix')$$,'a committed transition (built-in template)');
select lives_ok($$select public.portal_set_application_status('42000000-0000-0000-0000-0000000000b2','action_required','needs fix again')$$,'the same request repeated is a no-op');
reset role;
select is((select count(*)::int from public.admission_event_outbox where application_id='42000000-0000-0000-0000-0000000000b2' and event='application_status_changed')-(select events from p07_base),1,'a committed transition yields exactly one outbox event, even when requested twice');
select is((select count(*)::int from public.notification_deliveries where application_id='42000000-0000-0000-0000-0000000000b2'),1,'one delivery for the one recipient');
select is((select recipient_email||'|'||subject||'|'||template_source||'|'||state from public.notification_deliveries where application_id='42000000-0000-0000-0000-0000000000b2'),'notify-admin@example.test|Application 42000000 is now action required|default|pending','the delivery is rendered from the built-in template and addressed in lower case');
select is((select count(*)::int from public.notification_deliveries where recipient_user in ('a0000000-0000-0000-0000-00000000000a','a0000000-0000-0000-0000-00000000000b','a0000000-0000-0000-0000-00000000000c')),0,'inactive, other-agency and unassigned profiles receive nothing');
select is((select count(*)::int from public.portal_notifications where recipient='a0000000-0000-0000-0000-000000000009' and application_id='42000000-0000-0000-0000-0000000000b2' and event='status_change'),1,'the in-app inbox notification is preserved');
select throws_ok($$insert into public.notification_deliveries(outbox_id,tenant_id,application_id,recipient_user,recipient_email,event,template_source,subject,body) select outbox_id,tenant_id,application_id,recipient_user,recipient_email,event,template_source,subject,body from public.notification_deliveries limit 1$$,'23505',null,'a recipient cannot receive the same event twice');
