 select '42000000-0000-0000-0000-0000000000b1','1a000000-0000-0000-0000-000000000002','application_submitted','{}'::jsonb from generate_series(1,7);
create temporary table p0702_d as select row_number() over (order by seq)::int n, id from public.notification_deliveries where state='pending';
create temporary table p0702_c(n int, id uuid, lease uuid, attempt int);
grant all on p0702_d, p0702_c to service_role;
select is((select count(*)::int from p0702_d),7,'seven fresh pending deliveries');
set local role service_role;
insert into p0702_c select 1, id, lease_token, attempt_count from public.notification_claim_delivery();
insert into p0702_c select 2, id, lease_token, attempt_count from public.notification_claim_delivery();
select is((select string_agg(c.n::text||':'||(c.id=d.id)::text||':'||c.attempt,',' order by c.n) from p0702_c c join p0702_d d on d.n=c.n),'1:true:1,2:true:1','claims take pending deliveries in order and never the same one twice');
select is(public.notification_record_attempt((select id from p0702_c where n=1),gen_random_uuid(),'accepted','pm-1',null,false,null),false,'a wrong lease cannot record an outcome');
select throws_ok($$select public.notification_record_attempt((select id from p0702_c where n=1),(select lease from p0702_c where n=1),'accepted',' ',null,false,null)$$,'22023',null,'an accepted outcome needs a provider message id');
select is(public.notification_record_attempt((select id from p0702_c where n=1),(select lease from p0702_c where n=1),'accepted','pm-1',null,false,null),true,'the lease holder records acceptance');
select is(public.notification_record_attempt((select id from p0702_c where n=1),(select lease from p0702_c where n=1),'accepted','pm-1',null,false,null),false,'a replayed outcome is refused');
select is(public.notification_apply_provider_event('Delivery:pm-1:','Delivery','pm-1','{}'),'applied','a delivery callback is applied');
select is(public.notification_apply_provider_event('Delivery:pm-1:','Delivery','pm-1','{}'),'duplicate','the same callback again is a duplicate');
select is(public.notification_apply_provider_event('Bounce:pm-1:77','Bounce','pm-1','{"type":"HardBounce"}'),'applied','a bounce after delivery is applied');
select is(public.notification_apply_provider_event('Delivery:pm-1:other','Delivery','pm-1','{}'),'applied','a late delivery callback is recorded');
select throws_ok($$select public.notification_apply_provider_event('x','Open','pm-1','{}')$$,'22023',null,'an unsupported event type is rejected');
select is(public.notification_apply_provider_event('Delivery:pm-future:','Delivery','pm-future','{}'),'unmatched','a callback for an unknown message is kept, not applied');
select is(public.notification_record_attempt((select id from p0702_c where n=2),(select lease from p0702_c where n=2),'accepted','pm-future',null,false,null),true,'the second delivery is accepted afterwards');
reset role;
select is((select state||'|'||coalesce(last_error_code,'') from public.notification_deliveries where id=(select id from p0702_c where n=1)),'bounced|HardBounce','callbacks only move a delivery forward (a late delivery never undoes a bounce)');
select is((select state from public.notification_deliveries where id=(select id from p0702_c where n=2)),'delivered','an early callback is applied once the message id is recorded');
select is((select count(*)::int from public.notification_provider_events where provider_message_id='pm-1'),3,'every distinct callback is stored exactly once');
select is((select count(*)::int from public.notification_delivery_attempts where delivery_id in (select id from p0702_c)),2,'each accepted attempt is recorded');
set local role service_role;
insert into p0702_c select 3, id, lease_token, attempt_count from public.notification_claim_delivery();
select is(public.notification_record_attempt((select id from p0702_c where n=3),(select lease from p0702_c where n=3),'failed',null,'rate_limit',true,600),true,'a rate-limited attempt is recorded for retry');
insert into p0702_c select 4, id, lease_token, attempt_count from public.notification_claim_delivery();
select is((select (c.id=d.id)::text from p0702_c c join p0702_d d on d.n=4 where c.n=4),'true','a delivery waiting for its retry time is skipped');
select is(public.notification_record_attempt((select id from p0702_c where n=4),(select lease from p0702_c where n=4),'unknown',null,'timeout',false,null),true,'a timed-out request is recorded as unknown');
reset role;
select is((select state from public.notification_deliveries where id=(select id from p0702_c where n=4)),'unknown','an unknown outcome is never retried automatically');
update public.notification_deliveries set next_attempt_at=now() where id=(select id from p0702_c where n=3);
set local role service_role;
insert into p0702_c select 33, id, lease_token, attempt_count from public.notification_claim_delivery();
select is(public.notification_record_attempt((select id from p0702_c where n=33),(select lease from p0702_c where n=33),'failed',null,'rate_limit',true,600),true,'attempt 2 fails and is retried');
reset role;
update public.notification_deliveries set next_attempt_at=now() where id=(select id from p0702_c where n=3);
set local role service_role;
insert into p0702_c select 333, id, lease_token, attempt_count from public.notification_claim_delivery();
select is(public.notification_record_attempt((select id from p0702_c where n=333),(select lease from p0702_c where n=333),'failed',null,'rate_limit',true,600),true,'attempt 3 fails');
reset role;
select is((select state||'|'||attempt_count||'|'||last_error_code from public.notification_deliveries where id=(select id from p0702_c where n=3)),'failed|3|rate_limit','retries are bounded: the third failure dead-letters the delivery');
select is((select count(*)::int from public.notification_delivery_attempts where delivery_id=(select id from p0702_c where n=3)),3,'all three attempts are recorded');
set local role service_role;
insert into p0702_c select 5, id, lease_token, attempt_count from public.notification_claim_delivery();
reset role;
update public.notification_deliveries set lease_expires_at=now()-interval '1 second' where id=(select id from p0702_c where n=5);
