select throws_ok($$select public.notification_apply_provider_event('k','Delivery','pm-1','{}')$$,'42501',null,'browser roles cannot inject provider callbacks');
reset role;
select is(public.notification_render('{{reference}} / {{institution}}','{"reference":"A-1","institution":"{{reference}}"}'),'A-1 / {{reference}}','a value that looks like a placeholder is never expanded');
