reset role;
set local request.jwt.claim.sub='';
insert into public.admission_event_outbox(application_id,tenant_id,event,payload) values ('47000000-0000-0000-0000-000000000001',null,'application_status_changed','{"from":"under_review","to":"offer_issued"}');
select is((select count(*)::int from public.notification_deliveries where application_id='47000000-0000-0000-0000-000000000001' and state='pending'),1,'once the scope is activated, new events create pending deliveries');
select is((select count(*)::int from public.notification_deliveries where application_id='47000000-0000-0000-0000-000000000001' and state='suppressed' and state_reason='legacy_scope_not_activated'),1,'and the earlier suppressed delivery stays suppressed');
set local request.jwt.claim.sub='a0000000-0000-0000-0000-000000000003';
set local role authenticated;
select lives_ok($$select public.notification_set_activation(null,false,'Pause legacy')$$,'the legacy scope is paused again');
reset role;
set local request.jwt.claim.sub='';
insert into public.admission_event_outbox(application_id,tenant_id,event,payload) values ('47000000-0000-0000-0000-000000000001',null,'application_status_changed','{"from":"offer_issued","to":"offer_accepted"}');
select is((select count(*)::int from public.notification_deliveries where application_id='47000000-0000-0000-0000-000000000001' and state='pending'),1,'pausing does not touch what is already pending');
select is((select count(*)::int from public.notification_deliveries where application_id='47000000-0000-0000-0000-000000000001' and state_reason='legacy_scope_not_activated'),2,'but events during the pause are suppressed');
set local request.jwt.claim.sub='a0000000-0000-0000-0000-000000000003';
set local role authenticated;
select lives_ok($$select public.notification_set_activation(null,true,'Legacy scope resumed')$$,'the scope is activated again');
reset role;
select is((select count(*)::int from public.notification_deliveries where application_id='47000000-0000-0000-0000-000000000001' and state='pending'),0,'activating again releases nothing from before: the old pending delivery is suppressed');
select is((select count(*)::int from public.notification_deliveries where application_id='47000000-0000-0000-0000-000000000001' and state_reason='created_before_activation'),1,'with the reason created_before_activation');
set local request.jwt.claim.sub='';
insert into public.admission_event_outbox(application_id,tenant_id,event,payload) values ('47000000-0000-0000-0000-000000000001',null,'application_status_changed','{"from":"offer_accepted","to":"coe_issued"}');
set local role service_role;
select is((select count(*)::int from public.notification_claim_delivery() where tenant_id is null),1,'a delivery created after the activation is claimable');
reset role;
select is((select count(*)::int from public.notification_deliveries where application_id='47000000-0000-0000-0000-000000000001' and state in ('sending','sent','unknown')),1,'and exactly that one is in flight');
-- The claim itself refuses anything older than the activation, even if a sweep were missed.
insert into public.admission_event_outbox(application_id,tenant_id,event,payload) values ('47000000-0000-0000-0000-000000000001',null,'application_status_changed','{"from":"coe_issued","to":"enrolled"}');
update public.notification_deliveries set created_at=(select approved_at from public.notification_activation where tenant_id is null and revoked_at is null)-interval '1 minute' where application_id='47000000-0000-0000-0000-000000000001' and state='pending';
set local role service_role;
select is((select count(*)::int from public.notification_claim_delivery() where tenant_id is null),0,'the claim ignores a pending delivery that predates the activation');
reset role;
select is((select state from public.notification_deliveries where application_id='47000000-0000-0000-0000-000000000001' and created_at<(select approved_at from public.notification_activation where tenant_id is null and revoked_at is null) and state='pending' limit 1),'pending','which stays pending (never sent) until the next activation suppresses it');
-- Tenant scope: backlog built up while an institution was active is not released by a pause and resume.
set local request.jwt.claim.sub='a0000000-0000-0000-0000-000000000003';
set local request.headers='{"x-tenant-domain":"b.p06.example.test"}';
reset role;
insert into public.admission_event_outbox(application_id,tenant_id,event,payload) values ('45000000-0000-0000-0000-000000000004','1a000000-0000-0000-0000-000000000002','application_submitted','{}');
select is((select count(*)::int from public.notification_deliveries where application_id='45000000-0000-0000-0000-000000000004' and state='pending'),1,'an activated institution still creates pending deliveries');
set local role authenticated;
select lives_ok($$select public.notification_set_activation('1a000000-0000-0000-0000-000000000002',false,'Pause institution')$$,'the institution is paused');
select lives_ok($$select public.notification_set_activation('1a000000-0000-0000-0000-000000000002',true,'Resume institution after review')$$,'and resumed');
reset role;
select is((select count(*)::int from public.notification_deliveries where application_id='45000000-0000-0000-0000-000000000004' and state='pending'),0,'the backlog from before the resume is suppressed, not released');
select is((select count(*)::int from public.notification_deliveries where application_id='45000000-0000-0000-0000-000000000004' and state_reason='created_before_activation'),1,'with the reason created_before_activation');
select is((select count(*)::int from public.notification_deliveries where state in ('sending','sent','unknown','delivered','bounced','complained','failed') and state_reason='created_before_activation'),0,'deliveries already sent or in flight are never rewritten');
select * from finish();
rollback;
